import os
import sys
import json
import urllib.request
import urllib.error
import subprocess

def get_openai_audio(text, chunk_index):
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        return False

    url = "https://api.openai.com/v1/audio/speech"
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json"
    }
    data = {
        "model": "tts-1",
        "input": text,
        "voice": "onyx"
    }

    try:
        req = urllib.request.Request(url, json.dumps(data).encode('utf-8'), headers)
        with urllib.request.urlopen(req) as response:
            with open(f"chunk_{chunk_index:03d}.mp3", "wb") as f:
                f.write(response.read())
        return True
    except Exception as e:
        print(f"OpenAI TTS failed: {e}")
        return False

def get_elevenlabs_audio(text, chunk_index):
    api_key = os.environ.get("ELEVENLABS_API_KEY")
    if not api_key:
        return False

    # Using a default voice ID (Adam - standard male voice)
    voice_id = "pNInz6obpgDQGcFmaJgB" 
    url = f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}"
    headers = {
        "xi-api-key": api_key,
        "Content-Type": "application/json"
    }
    data = {
        "text": text,
        "model_id": "eleven_monolingual_v1",
        "voice_settings": {
            "stability": 0.5,
            "similarity_boost": 0.5
        }
    }

    try:
        req = urllib.request.Request(url, json.dumps(data).encode('utf-8'), headers)
        with urllib.request.urlopen(req) as response:
            with open(f"chunk_{chunk_index:03d}.mp3", "wb") as f:
                f.write(response.read())
        return True
    except Exception as e:
        print(f"ElevenLabs TTS failed: {e}")
        return False

def split_text(text, max_chars=4000):
    chunks = []
    current_chunk = ""
    paragraphs = text.split('\n')

    for para in paragraphs:
        if len(current_chunk) + len(para) < max_chars:
            current_chunk += para + "\n"
        else:
            if current_chunk:
                chunks.append(current_chunk)
            current_chunk = para + "\n"
            # If a single paragraph is too long, we might need to split it further
            # For now, assuming paragraphs are reasonable
            if len(current_chunk) > max_chars:
                 # simple split by sentence or just hard cut if needed
                 # keeping it simple: just append it, API might error if strictly enforced > 4096
                 # OpenAI limit is 4096.
                 pass 
    if current_chunk:
        chunks.append(current_chunk)
    return chunks

def main():
    files = ["essay1.txt", "essay2.txt"]
    full_text = ""
    for fpath in files:
        if os.path.exists(fpath):
            with open(fpath, "r", encoding="utf-8") as f:
                full_text += f.read() + "\n\n"
        else:
            print(f"Warning: {fpath} not found")

    if not full_text.strip():
        print("No text to process")
        sys.exit(1)

    chunks = split_text(full_text)
    print(f"Split text into {len(chunks)} chunks")

    # Try ElevenLabs first, then OpenAI
    use_elevenlabs = os.environ.get("ELEVENLABS_API_KEY") is not None
    use_openai = os.environ.get("OPENAI_API_KEY") is not None

    print(f"ElevenLabs available: {use_elevenlabs}")
    print(f"OpenAI available: {use_openai}")

    processed_chunks = []

    for i, chunk in enumerate(chunks):
        print(f"Processing chunk {i+1}/{len(chunks)}...")
        success = False
        if use_elevenlabs:
            success = get_elevenlabs_audio(chunk, i)

        if not success and use_openai:
            success = get_openai_audio(chunk, i)

        if not success:
            print(f"Failed to convert chunk {i+1}")
            # Try local fallback?
            # Creating a dummy file or using espeak if critical
            # For this task, we will just skip or fail.
            pass
        else:
            processed_chunks.append(f"chunk_{i:03d}.mp3")

    if not processed_chunks:
        print("No audio chunks created.")
        sys.exit(1)

    # Concatenate using ffmpeg
    with open("files.txt", "w") as f:
        for chunk in processed_chunks:
            f.write(f"file '{chunk}'\n")

    cmd = ["ffmpeg", "-f", "concat", "-safe", "0", "-i", "files.txt", "-c", "copy", "/root/audiobook.mp3", "-y"]
    subprocess.run(cmd, check=True)

    # Cleanup
    for chunk in processed_chunks:
        os.remove(chunk)
    os.remove("files.txt")

    print("Audiobook created at /root/audiobook.mp3")

if __name__ == "__main__":
    main()

